import * as babel from '@babel/core';
import type { NodePath } from '@babel/traverse';
/**
 * @file quality-gate.ts
 * @description Automated Quality Gate auditing tool outputs and file modifications generated by AI agents.
 * Validates TypeScript compliance, architectural boundaries, design system tokens, RLS policies, and error handling.
 */

export interface QualityCheckViolation {
  filePath?: string;
  lineNumber?: number;
  ruleId: string;
  severity: 'CRITICAL' | 'WARNING';
  description: string;
  remediationSnippet?: string;
}

export interface QualityAuditResult {
  passed: boolean;
  score: number; // 0 to 100
  totalChecks: number;
  criticalViolations: QualityCheckViolation[];
  warnings: QualityCheckViolation[];
  auditTimestamp: string;
}

export interface StructuredThinkingValidationResult {
  readonly compliant: boolean;
  readonly detectedFormat: 'format-a-inline' | 'format-b-native' | 'format-c-tracer' | 'none';
  readonly completedPhases: readonly string[];
  readonly missingPhases: readonly string[];
  readonly violationCode?: 'THINKING_MISSING' | 'INCOMPLETE_STM_PHASES';
  readonly remediationDirective?: string;
}

const STM_PHASE_PATTERNS: ReadonlyArray<{ readonly phaseId: string; readonly regex: RegExp }> = [
  { phaseId: 'Phase 1 (Comprehension)', regex: /Phase\s*1\b|Comprehension/i },
  { phaseId: 'Phase 2 (Evidence)', regex: /Phase\s*2\b|Evidence/i },
  { phaseId: 'Phase 3 (Design)', regex: /Phase\s*3\b|Design|Solution/i },
  { phaseId: 'Phase 4 (Criticism)', regex: /Phase\s*4\b|Criticism|Critique/i },
  { phaseId: 'Phase 5 (Contract)', regex: /Phase\s*5\b|Contract|Verification/i },
];

export class QualityGate {
  /**
   * Deterministic STM-0 Structured Thinking validator (`skill://structured-thinking` §3 & §7).
   * Verifies that non-trivial agent outputs or AGENT_TRACER entries externalize all 5 MTP phases
   * via Format A (`<structured-thinking>`), Format B (`<thinking>`), or Format C (`Phase 1..5`).
   */
  public static validateStructuredThinking(content: string): StructuredThinkingValidationResult {
    const trimmed = content.trim();
    if (!trimmed) {
      return {
        compliant: false,
        detectedFormat: 'none',
        completedPhases: [],
        missingPhases: STM_PHASE_PATTERNS.map((p) => p.phaseId),
        violationCode: 'THINKING_MISSING',
        remediationDirective:
          'Output is empty. Externalize STM-0 5-phase thinking (<structured-thinking> or AGENT_TRACER Phase 1..5) before mutating code.',
      };
    }

    const hasFormatA =
      /<structured-thinking>[\s\S]*?<\/structured-thinking>/i.test(trimmed) ||
      trimmed.includes('<structured-thinking>');
    const hasFormatB = /<thinking>[\s\S]*?<\/thinking>/i.test(trimmed);
    const hasFormatC =
      /\*{0,2}Phase\s*1\s*\(Comprehension\)/i.test(trimmed) ||
      /##\s*Phase\s*1:\s*Situational\s*Comprehension/i.test(trimmed);

    const detectedFormat: StructuredThinkingValidationResult['detectedFormat'] = hasFormatA
      ? 'format-a-inline'
      : hasFormatB
        ? 'format-b-native'
        : hasFormatC
          ? 'format-c-tracer'
          : 'none';

    const completedPhases: string[] = [];
    const missingPhases: string[] = [];

    for (const phase of STM_PHASE_PATTERNS) {
      if (phase.regex.test(trimmed)) {
        completedPhases.push(phase.phaseId);
      } else {
        missingPhases.push(phase.phaseId);
      }
    }

    if (detectedFormat === 'none' && completedPhases.length === 0) {
      return {
        compliant: false,
        detectedFormat: 'none',
        completedPhases: [],
        missingPhases: STM_PHASE_PATTERNS.map((p) => p.phaseId),
        violationCode: 'THINKING_MISSING',
        remediationDirective:
          'THINKING_MISSING: Engage STM-0 Structured Thinking (Format A <structured-thinking>, Format B <thinking>, or Format C AGENT_TRACER Phase 1..5) before executing code changes.',
      };
    }

    if (missingPhases.length > 0) {
      return {
        compliant: false,
        detectedFormat,
        completedPhases,
        missingPhases,
        violationCode: 'INCOMPLETE_STM_PHASES',
        remediationDirective: `INCOMPLETE_STM_PHASES: Missing ${missingPhases.join(', ')}. Complete all 5 STM-0 phases before mutating files.`,
      };
    }

    return {
      compliant: true,
      detectedFormat: detectedFormat === 'none' ? 'format-c-tracer' : detectedFormat,
      completedPhases,
      missingPhases: [],
    };
  }

  /**
   * Audits code or diff content against strict monorepo rules.
   */
  public static auditContent(content: string, filePath?: string): QualityAuditResult {
    const violations: QualityCheckViolation[] = [];
    const isUIFile =
      filePath?.includes('/packages/ui/') ||
      (filePath?.includes('/libs/features/') && filePath?.includes('/ui/'));
    const isSQLFile = filePath?.endsWith('.sql');

    const lines = content.split('\n');

    try {
      if (
        filePath &&
        (filePath.endsWith('.ts') ||
          filePath.endsWith('.tsx') ||
          filePath.endsWith('') ||
          filePath.endsWith('.jsx'))
      ) {
        const ast = babel.parseSync(content, {
          filename: filePath,
          presets: ['@babel/preset-typescript'],
        });

        if (ast) {
          babel.traverse(ast, {
            ImportDeclaration(path: NodePath<babel.types.ImportDeclaration>) {
              const source = path.node.source.value;
              if (isUIFile && (source === '@repo/database' || source === '@repo/supabase')) {
                violations.push({
                  filePath,
                  lineNumber: path.node.loc?.start?.line || 0,
                  ruleId: 'NO_DIRECT_DB_IMPORT_IN_UI',
                  severity: 'CRITICAL',
                  description:
                    'Pure UI component imports database or supabase package directly. Must use feature data-access libraries.',
                  remediationSnippet: 'Refactor import to use @repo/<feature>/data-access',
                });
              }
            },
          });
        }
      }
    } catch (err) {
      console.warn('AST Parser fallback due to syntax error:', err);
    }

    lines.forEach((line, idx) => {
      const lineNum = idx + 1;

      // 1. Direct DB / Supabase import fallback inside pure UI files
      if (
        isUIFile &&
        violations.every((v) => v.ruleId !== 'NO_DIRECT_DB_IMPORT_IN_UI') &&
        /^\s*(?:import|export)\s+[\s\S]*?from\s+['"]@repo\/(database|supabase)(?:\/[^'"]*)?['"]/.test(
          line
        )
      ) {
        violations.push({
          filePath,
          lineNumber: lineNum,
          ruleId: 'NO_DIRECT_DB_IMPORT_IN_UI',
          severity: 'CRITICAL',
          description:
            'Pure UI component imports database or supabase package directly. Must use feature data-access libraries.',
          remediationSnippet: 'Refactor import to use @repo/<feature>/data-access',
        });
      }

      // 2. Forbidden Dark Mode Class Check
      if (/\bdark:[a-zA-Z0-9_/-]+/.test(line)) {
        violations.push({
          filePath,
          lineNumber: lineNum,
          ruleId: 'FORBIDDEN_DARK_MODE_CLASS',
          severity: 'CRITICAL',
          description:
            "Use of responsive 'dark:' class is prohibited. Application theme is strictly light-mode.",
          remediationSnippet: "Remove 'dark:' prefix and rely on light OKLCH theme tokens.",
        });
      }

      // 3. Forbidden Raw Tailwind Shadow Check
      const shadowMatch = line.match(
        /\bshadow-(blue|red|emerald|amber|purple|pink|indigo)-[0-9]+\b/
      );
      if (shadowMatch) {
        violations.push({
          filePath,
          lineNumber: lineNum,
          ruleId: 'FORBIDDEN_TAILWIND_SHADOW',
          severity: 'CRITICAL',
          description: `Raw colored shadow class '${shadowMatch[0]}' is forbidden. Use OKLCH theme tokens (shadow-card, shadow-window, shadow-diffusion-*).`,
          remediationSnippet:
            "Replace with 'shadow-card' or approved shadow token from @repo/theme.",
        });
      }

      // 4. Untyped 'any' Parameter / Cast Check
      if (
        /:\s*any\b/.test(line) &&
        !line.includes('eslint-disable') &&
        !line.includes('// @ts-ignore')
      ) {
        violations.push({
          filePath,
          lineNumber: lineNum,
          ruleId: 'NO_IMPLICIT_OR_EXPLICIT_ANY',
          severity: 'WARNING',
          description:
            "Explicit 'any' type annotation detected. Provide strict TypeScript interface or unknown.",
          remediationSnippet: "Use strict type interface or 'unknown' with type guard.",
        });
      }

      // 5. Raw SQL String Concatenation Security Check
      if (/(SELECT|INSERT|UPDATE|DELETE)\s+.*\+\s*[a-zA-Z0-9_]+/i.test(line)) {
        violations.push({
          filePath,
          lineNumber: lineNum,
          ruleId: 'NO_DYNAMIC_SQL_CONCAT',
          severity: 'CRITICAL',
          description: 'Dynamic SQL string concatenation detected. Vulnerable to SQL injection.',
          remediationSnippet: 'Use parameterized queries or Kysely query builder.',
        });
      }

      // 6. RLS Policy Subquery Check in SQL files
      if (isSQLFile && line.toUpperCase().includes('CREATE POLICY')) {
        if (
          !content.includes('(SELECT auth.uid())') &&
          !content.includes('(SELECT public.is_admin())')
        ) {
          violations.push({
            filePath,
            lineNumber: lineNum,
            ruleId: 'RLS_INITPLAN_OPTIMIZATION_MISSING',
            severity: 'CRITICAL',
            description:
              "RLS CREATE POLICY missing InitPlan subquery pattern '(SELECT auth.uid())'. Direct auth.uid() disables per-query plan caching.",
            remediationSnippet: 'Wrap auth call: USING ((SELECT auth.uid()) = user_id)',
          });
        }
      }
    });

    const criticals = violations.filter((v) => v.severity === 'CRITICAL');
    const warnings = violations.filter((v) => v.severity === 'WARNING');
    const totalChecks = 6;
    const score = Math.max(0, 100 - criticals.length * 20 - warnings.length * 5);

    return {
      passed: criticals.length === 0,
      score,
      totalChecks,
      criticalViolations: criticals,
      warnings,
      auditTimestamp: new Date().toISOString(),
    };
  }

  /**
   * Generates formatted markdown diagnostic feedback for AI agent self-reflection.
   */
  public static formatDiagnosticFeedback(audit: QualityAuditResult): string {
    if (audit.passed && audit.warnings.length === 0) {
      return '✅ Quality Gate Verdict: 100% PASS. Zero architectural, type, or design violations detected.';
    }

    let feedback = `### ⚠️ Quality Gate Verdict: ${audit.passed ? 'PASSED WITH WARNINGS' : 'FAILED'}\n`;
    feedback += `Compliance Score: ${audit.score}/100\n\n`;

    if (audit.criticalViolations.length > 0) {
      feedback += '#### 🛑 Critical Violations (Must Remediate Immediately):\n';
      audit.criticalViolations.forEach((v, i) => {
        feedback += `${i + 1}. **[${v.ruleId}]** in \`${v.filePath || 'generated content'}\` (Line ${v.lineNumber || 'N/A'})\n`;
        feedback += `   - **Defect**: ${v.description}\n`;
        if (v.remediationSnippet) {
          feedback += `   - **Remediation**: ${v.remediationSnippet}\n`;
        }
      });
      feedback += '\n';
    }

    if (audit.warnings.length > 0) {
      feedback += '#### ⚠️ Warnings:\n';
      audit.warnings.forEach((v, i) => {
        feedback += `${i + 1}. **[${v.ruleId}]** in \`${v.filePath || 'generated content'}\` (Line ${v.lineNumber || 'N/A'})\n`;
        feedback += `   - **Defect**: ${v.description}\n`;
      });
    }

    return feedback;
  }
}
